// apps/ury/ury/public/js/setup/ury_setup_wizard.js

console.log("🔥 URY setup wizard file loaded");

frappe.setup.on("before_load", function () {
	console.log("🔥 URY before_load fired");

	if (!window.erpnext?.setup?.slides_settings) return;

	const org_slide = erpnext.setup.slides_settings.find(
		s => s.name === "organization"
	);

	if (!org_slide) return;

	if (org_slide.fields.some(f => f.fieldname === "setup_ury_demo")) return;

	const demo_index = org_slide.fields.findIndex(
		f => f.fieldname === "setup_demo"
	);

	if (demo_index === -1) return;

	org_slide.fields.splice(demo_index + 1, 0, {
		fieldname: "setup_ury_demo",
		label: __("Generate URY Demo Data"),
		fieldtype: "Check",
		description: __("Create URY-specific demo data"),
	});

	console.log("✅ URY checkbox injected");
});